const money=v=>n(v)===null?'—':'¥'+num(v),signed=v=>n(v)===null?'—':(n(v)>0?'+':'')+num(v),pct=v=>n(v)===null?'—':signed(v)+'%',tone=v=>n(v)>0?'up':n(v)<0?'down':'';
