const titles={workbench:'对话工作台',library:'策略库',holdings:'我的持仓',watchlist:'我的自选',plans:'我的计划',history:'运行历史',account:'账户与连接',settings:'模型与推理设置'};
const state={csrf:'',catalog:[],variants:[],plans:[],runs:[],events:[],watchlist:[],showcases:{},showcaseLoading:new Set(),planPerformanceLoading:false,nav:'workbench',selected:null,variant:null,result:null,job:null,busy:false,detailTab:'editor',paramEditing:false,paramsExpanded:false,pendingCode:'',holdings:null,holdingsError:'',analysis:null,analysisError:'',accountBusy:false,accountLoginMode:'login',accountLoginMessage:'',drill:null,defaultLoading:null};
