async function api(path,body){const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),120000);try{const r=await fetch(path,{method:body===undefined?'GET':'POST',cache:'no-store',signal:ctrl.signal,headers:body===undefined?{}:{'Content-Type':'application/json','X-Workbench-Token':state.csrf},body:body===undefined?undefined:JSON.stringify(body)});const p=await r.json();if(!r.ok||!p.ok)throw new Error(p.error?.message||'本地服务请求失败。');return p.data}catch(e){if(e.name==='AbortError')throw new Error('请求超时，请稍后重试。');throw e}finally{clearTimeout(timer)}}
async function desktopCall(p){const r=await p;if(!r?.ok)throw new Error(r?.error||'桌面 Agent 操作失败。');return r.data}
function toast(text){const node=$('#panda-toast');if(!node)return;node.textContent=text;node.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('show'),4200)}
function button(label,action,attrs='',cls=''){return `<button type="button" class="panda-button ${cls}" data-action="${action}" ${attrs}>${label}</button>`}
