function heading(eyebrow,title,desc,actions=''){return `<div class="panda-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div><div class="panda-heading-actions">${actions}</div></div>`}

function inlineMarkdown(value){let text=esc(value);return text.replace(/`([^`\n]+)`/g,'<code>$1</code>').replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/\[([^\]]+)\]\((https:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noreferrer">$1</a>')}
function renderMarkdown(value){const parts=String(value||'').split(/```/);return parts.map((part,index)=>{if(index%2)return `<pre><code>${esc(part.replace(/^\w+\n/,'').replace(/\n$/,''))}</code></pre>`;const lines=part.split('\n'),out=[];for(let i=0;i<lines.length;){const line=lines[i];if(!line.trim()){i++;continue}if(/^\s*[-*]\s+/.test(line)){const items=[];while(i<lines.length&&/^\s*[-*]\s+/.test(lines[i]))items.push(lines[i++].replace(/^\s*[-*]\s+/,''));out.push(`<ul>${items.map(x=>`<li>${inlineMarkdown(x)}</li>`).join('')}</ul>`);continue}if(/^\s*\d+\.\s+/.test(line)){const items=[];while(i<lines.length&&/^\s*\d+\.\s+/.test(lines[i]))items.push(lines[i++].replace(/^\s*\d+\.\s+/,''));out.push(`<ol>${items.map(x=>`<li>${inlineMarkdown(x)}</li>`).join('')}</ol>`);continue}const h=line.match(/^(#{1,3})\s+(.+)$/);if(h){out.push(`<h${h[1].length+2}>${inlineMarkdown(h[2])}</h${h[1].length+2}>`);i++;continue}const p=[line];i++;while(i<lines.length&&lines[i].trim()&&!/^(#{1,3})\s+|^\s*[-*]\s+|^\s*\d+\.\s+/.test(lines[i]))p.push(lines[i++]);out.push(`<p>${p.map(inlineMarkdown).join('<br>')}</p>`)}return out.join('')}).join('')}

function defaultParamsMatch(run,item){return run?.status==='ok'&&run.strategyVersion===item.version&&(item.params||[]).every(spec=>String(run.parameters?.[spec.key]??'')===String(item.defaultParams?.[spec.key]??spec.default??''))}
function showcaseRun(item){return state.runs.filter(run=>run.strategyId===item.id&&defaultParamsMatch(run,item)&&n(run.metrics?.excessReturnPct)!==null).sort((a,b)=>(n(b.metrics?.excessReturnPct)??-Infinity)-(n(a.metrics?.excessReturnPct)??-Infinity))[0]||null}
function showcaseBest(item){return state.showcases[item.id]?.best||showcaseRun(item)?.result||null}
function sortedStrategies(){return state.catalog.map((item,index)=>({item,index,excess:n(showcaseBest(item)?.metrics?.excessReturnPct)})).sort((a,b)=>(b.excess??-Infinity)-(a.excess??-Infinity)||a.index-b.index).map(row=>row.item)}
function strategyCard(item){const variant=currentVariant(item.id),report=state.showcases[item.id],best=showcaseBest(item),m=best?.metrics||{},absolute=m.absoluteReturnPct??m.returnPct,excess=m.excessReturnPct,target=best?.candidateName||best?.fundCode||'固定行业基金池',count=report?.candidateCount||best?.showcase?.candidateCount||item.showcaseCandidates?.length||1,scope=count>1?`${count} 只固定候选中超额收益最高`:'Skill 固定案例',performance=best?`<div class="strategy-performance"><small>默认参数 · ${esc(scope)} · ${esc(target)}</small><div><span>策略累计收益 <b class="${tone(absolute)}">${pct(absolute)}</b></span><span>超额收益 <b class="${tone(excess)}">${pct(excess)}</b></span><span>年化波动率 <b>${n(m.volatilityPct)===null?'—':num(m.volatilityPct)+'%'}</b></span></div><em>超额 = 策略同期收益 − 同期基准 · 数据截至 ${esc(best.dataAsOf||'—')}</em></div>`:state.showcaseLoading.has(item.id)?`<div class="strategy-performance empty"><small>正在验证默认案例</small><div><span>逐只复算候选基金与同期基准</span></div><em>完成后按超额收益排序</em></div>`:`<div class="strategy-performance empty"><small>默认参数参考回测</small><div><span>尚无通过数据校验的结果</span></div><em>进入详情后重新验证候选池</em></div>`;return `<article class="panda-strategy-card"><div class="strategy-card-head"><span class="strategy-glyph">${esc(item.symbol||'◇')}</span><span class="strategy-badge">${esc(item.category)} · v${esc(item.version)}</span></div><h3>${esc(variant?.name||item.name)}</h3><p>${esc(item.description)}</p>${performance}<div class="strategy-card-footer"><small>${esc(item.suitableFor)}<br>代价：${esc(item.tradeoff)}</small>${button('查看策略','open-strategy',`data-id="${esc(item.id)}"`,'primary')}</div></article>`}
function conversationActive(){return D.messages.length>0||D.running||Boolean(D.pendingInput)}
function home(){if(conversationActive())return '<div id="agent-conversation-host" class="panda-conversation-page"></div>';const hc=state.holdings?.funds?.length,watch=state.watchlist.length,active=state.plans.filter(x=>x.status==='active').length;return `<div class="panda-workbench-idle"><div class="panda-start-hero"><h1>想从哪儿开始？</h1><p>选择策略研究，或直接把目标交给 ParadoxAI。</p></div><section class="panda-workspace-block strategy-block"><div class="panda-section-head"><div><span>01</span><h2>策略</h2><p>按默认回测超额收益降序 · 参数可编辑 · 结果可追溯</p></div><button class="link-button" data-nav="library">查看全部</button></div><div class="panda-strategy-grid">${sortedStrategies().map(strategyCard).join('')}</div></section><section class="panda-workspace-block my-block"><div class="panda-section-head"><div><span>02</span><h2>我的</h2><p>真实账户、研究清单与跟踪计划</p></div></div><div class="panda-my-grid"><button data-nav="holdings"><span>◫</span><strong>我的持仓</strong><small>${hc===undefined?'等待连接':hc+' 只真实持仓'}</small></button><button data-nav="watchlist"><span>☆</span><strong>我的自选</strong><small>${watch} 只本地自选</small></button><button data-nav="plans"><span>▤</span><strong>我的计划</strong><small>${active} 份正在跟踪</small></button></div></section><div id="agent-composer-host" class="panda-bottom-composer-host"></div></div>`}
function library(){return `${heading('STRATEGY LIBRARY','策略','固定候选池使用相同默认参数和同期真实数据回测，按超额收益降序排列；历史结果不代表未来表现。')}<div class="panda-strategy-grid">${sortedStrategies().map(strategyCard).join('')}</div>`}
function paramField(spec,params,editable,index){const value=params?.[spec.key]??spec.default??'',range=spec.choices?`可选：${spec.choices.join(' / ')}`:`范围 ${spec.min}–${spec.max} ${spec.unit||''}`,hidden=!state.paramsExpanded&&index>=3?' is-collapsed':'';const control=editable?(spec.choices?`<select name="param-${esc(spec.key)}">${spec.choices.map(c=>`<option value="${esc(c)}" ${String(c)===String(value)?'selected':''}>${esc(c)}</option>`).join('')}</select>`:`<div class="panda-number-input"><input type="number" name="param-${esc(spec.key)}" value="${esc(value)}" min="${esc(spec.min)}" max="${esc(spec.max)}" step="${esc(spec.step||1)}" required><span>${esc(spec.unit||'')}</span></div>`):`<div class="panda-param-value"><strong>${esc(value)}</strong><span>${esc(spec.unit||'')}</span></div>`;return `<div class="panda-field panda-param-card${hidden}"><label><b>${esc(spec.label)}</b><span>：${esc(spec.help||'调整策略运行时使用的数值。')}</span></label>${control}<small>${esc(range)} · 默认 ${esc(spec.default)}</small></div>`}
function paramsFromForm(form,item){const raw=Object.fromEntries(new FormData(form)),params={};for(const spec of item.params||[])params[spec.key]=spec.choices?raw['param-'+spec.key]:Number(raw['param-'+spec.key]);if(String(raw.definition||'').trim()){let definition;try{definition=JSON.parse(raw.definition)}catch{throw new Error('受控策略定义不是有效 JSON。')}if(definition.engine!==item.id)throw new Error('策略引擎不可更换；请选择另一张策略卡。');if(!definition.parameters||typeof definition.parameters!=='object'||Array.isArray(definition.parameters))throw new Error('策略定义缺少 parameters。');const supported=new Set((item.params||[]).map(x=>x.key)),unknown=Object.keys(definition.parameters).filter(x=>!supported.has(x));if(unknown.length)throw new Error('当前 Skill 不支持参数：'+unknown.join('、'));for(const spec of item.params||[])if(Object.hasOwn(definition.parameters,spec.key))params[spec.key]=definition.parameters[spec.key]}return {raw,params}}
function ruleDefinition(item,params){return JSON.stringify({engine:item.id,baseVersion:item.version,parameters:params},null,2)}
function parameterModule(item,params,code,example,variant){const editable=state.paramEditing,entries=[];if(item.codeRequired===false){entries.push(`<div class="panda-field panda-param-card panda-fund-contract"><label><b>研究标的</b><span>：使用 Skill 固定行业基金池，回测会列出实际取数范围。</span></label><div class="panda-param-value"><strong>固定行业基金池</strong></div><input type="hidden" name="code" value=""></div>`)}else{entries.push(`<div class="panda-field panda-param-card panda-fund-contract"><label><b>场外基金代码</b><span>：默认使用策略卡中相同参数筛出的案例基金，也可以改为其他符合范围的基金。</span></label>${editable?`<input name="code" inputmode="numeric" maxlength="6" pattern="[0-9]{6}" placeholder="输入 6 位基金代码" value="${esc(code)}" required>`:`<div class="panda-param-value"><strong>${esc(code||'—')}</strong><span>${esc(example?.candidateName||'默认案例')}</span></div>`}<small>默认案例：${esc(example?.candidateName||example?.fundCode||item.defaultFundCode||'—')}</small></div>`)}const offset=entries.length;for(const [index,spec] of (item.params||[]).entries())entries.push(paramField(spec,params,editable,index+offset));const total=entries.length;return `<section class="panda-backtest-params"><input type="hidden" name="variantId" value="${esc(variant?.id||'')}"><input type="hidden" name="name" value="${esc(variant?.name||item.name)}"><input type="hidden" name="description" value="${esc(variant?.description||item.description)}"><div class="panda-backtest-params-head"><div><small>本次回测配置</small><strong>${editable?'修改参数后重新计算':'当前展示值与左侧回测一致'}</strong></div><div>${total>3?button(state.paramsExpanded?'收起参数':'展开全部 '+total+' 项','toggle-params','','quiet'):''}${button(editable?'取消修改':'修改参数',editable?'cancel-param-edit':'edit-params','',editable?'quiet':'primary')}</div></div><div class="panda-form-grid">${entries.join('')}</div>${editable?`<details class="panda-contract"><summary>查看受控策略合同</summary><pre>${esc(ruleDefinition(item,params))}</pre></details><div class="panda-detail-actions"><button class="panda-button primary" type="submit" name="intent" value="run" ${state.busy?'disabled':''}>${state.busy?'运行中…':'按当前参数重新回测'}</button><button class="panda-button" type="submit" name="intent" value="save">保存参数版本</button></div><div class="panda-code-state"><i></i> 只修改当前 Skill 支持的参数，服务端会校验范围和步长。</div>`:''}</section>`}

function jobPanel(){if(!state.job)return '';const stage={queued:'等待计算',validating:'参数校验','loading-data':'读取真实数据',calculating:'运行确定性回测',rendering:'整理结果',completed:'已完成',failed:'失败'}[state.job.stage]||state.job.stage;return `<section class="panda-job"><div class="panda-job-head"><strong>${esc(stage)}</strong><span>${esc(state.job.progress||0)}% · ${num((state.job.elapsedMs||0)/1000)} 秒</span></div><div class="panda-progress"><i style="width:${Math.max(0,Math.min(100,state.job.progress||0))}%"></i></div><div class="panda-stage-row">${['参数校验','读取数据','策略计算','整理结果'].map((x,i)=>`<span class="${(state.job.progress||0)>[10,30,65,90][i]?'done':''}">${x}</span>`).join('')}</div><details class="panda-run-logs" open><summary>运行日志</summary>${(state.job.logs||[]).map(x=>`<p><time>${esc(String(x.at||'').slice(11,19))}</time>${esc(x.message)}</p>`).join('')}</details></section>`}
function lineChart(rows,hasBenchmark=false,trades=[]){if(!rows?.length)return '';const first=key=>n(rows.find(r=>n(r[key])!==null&&n(r[key])!==0)?.[key]),baseValue=first('value'),baseBenchmark=first('benchmark'),plot=rows.map(r=>{const value=n(r.value),benchmark=n(r.benchmark);return {date:r.date,value:baseValue&&value!==null?(value/baseValue-1)*100:null,benchmark:hasBenchmark&&baseBenchmark&&benchmark!==null?(benchmark/baseBenchmark-1)*100:null}}),values=plot.flatMap(r=>[r.value,r.benchmark]).filter(v=>v!==null&&Number.isFinite(v));if(!values.length)return '';const lo=Math.min(0,...values),hi=Math.max(0,...values),pad=Math.max((hi-lo)*.12,2),min=lo-pad,max=hi+pad,left=64,right=694,top=20,bottom=226,width=right-left,height=bottom-top,x=i=>left+i/Math.max(1,plot.length-1)*width,y=v=>top+(max-v)/(max-min)*height,points=key=>plot.map((r,i)=>r[key]===null?'':`${x(i).toFixed(1)},${y(r[key]).toFixed(1)}`).filter(Boolean).join(' '),yTicks=Array.from({length:5},(_,i)=>max-(max-min)*i/4),xIndexes=[0,Math.floor((plot.length-1)/3),Math.floor((plot.length-1)*2/3),plot.length-1].filter((v,i,a)=>a.indexOf(v)===i),nearest=date=>{const target=Date.parse(date);let best=0,diff=Infinity;plot.forEach((r,i)=>{const d=Math.abs(Date.parse(r.date)-target);if(d<diff){best=i;diff=d}});return best},grouped=[...new Map((trades||[]).map(t=>[`${t.date}-${t.side}`,t])).values()],markerRows=grouped.length<=36?grouped:Array.from({length:36},(_,i)=>grouped[Math.round(i*(grouped.length-1)/35)]),markers=markerRows.map(t=>{const i=nearest(t.date),v=hasBenchmark&&plot[i]?.benchmark!==null?plot[i]?.benchmark:plot[i]?.value;if(v===null||v===undefined)return '';const cls=t.side==='buy'?'chart-buy':'chart-sell',label=t.side==='buy'?'买':'卖';return `<g class="chart-trade ${cls}"><circle cx="${x(i)}" cy="${y(v)}" r="4.5"><title>${esc(t.date)} · ${t.side==='buy'?'买入':'卖出'} · ${money(t.amount)}</title></circle><text x="${x(i)}" y="${y(v)-8}">${label}</text></g>`}).join('');return `<svg class="panda-chart" viewBox="0 0 720 270" role="img" aria-label="历史累计收益率曲线"><text class="axis-title" x="16" y="16">累计收益率</text>${yTicks.map(v=>`<g><line class="grid" x1="${left}" y1="${y(v)}" x2="${right}" y2="${y(v)}"/><text class="axis-label" x="${left-9}" y="${y(v)+3}">${v.toFixed(1)}%</text></g>`).join('')}<line class="zero-line" x1="${left}" y1="${y(0)}" x2="${right}" y2="${y(0)}"/><polyline class="strategy-line" points="${points('value')}"/>${hasBenchmark?`<polyline class="benchmark-line" points="${points('benchmark')}"/>`:''}${markers}${xIndexes.map(i=>`<text class="date" x="${x(i)}" y="252" text-anchor="${i===0?'start':i===plot.length-1?'end':'middle'}">${esc(plot[i]?.date||'')}</text>`).join('')}</svg>`}
function chart(result){const curve=result?.curve||[];return curve.length?lineChart(curve,true,result.trades||[]):'<div class="panda-result-empty"><div><span class="result-mark">◌</span><strong>暂无可绘制曲线</strong></div></div>'}
function tradesTable(result){const rows=result?.trades;if(!Array.isArray(rows))return '<div class="panda-history-note">这条旧记录只保存了指标摘要，未保存交易明细。</div>';if(!rows.length)return '<div class="panda-history-note">本次区间没有产生买卖动作。</div>';let units=0;const enriched=rows.map(x=>{if(result.fundCode&&n(x.nav)>0&&n(x.amount)!==null){units=Math.max(0,units+(x.side==='buy'?1:-1)*n(x.amount)/n(x.nav))}return {...x,displayHolding:n(x.holdingAmount)??(result.fundCode?units*n(x.nav):null)}});return `<div class="panda-table-wrap"><table class="panda-table"><thead><tr><th>日期</th><th>方向</th><th>净值</th><th>交易后持仓金额</th><th>当次交易金额</th><th>交易依据</th></tr></thead><tbody>${enriched.slice(-100).reverse().map(x=>`<tr><td>${esc(x.date)}</td><td><span class="trade-${esc(x.side)}">${x.side==='buy'?'买入':'卖出'}</span></td><td>${num(x.nav)}</td><td>${money(x.displayHolding)}</td><td><strong class="trade-${esc(x.side)}">${money(x.amount)}</strong></td><td>${esc(x.reason)}</td></tr>`).join('')}</tbody></table></div>`}
function resultView(result,allowPlan=true,parameterMarkup=''){if(!result)return `${parameterMarkup}<div class="panda-result-empty"><div><span class="result-mark">◌</span><strong>正在准备默认回测</strong><p>页面会按策略默认参数读取真实数据；缺少数据时将显示具体原因。</p></div></div>`;if(result.status!=='ok')return `${parameterMarkup}<div class="panda-result-blocked"><b>!</b><div><strong>暂无法判断</strong><p>${esc((result.missingData||[]).join('；')||'数据接口未返回完整结果。')}</p><small>来源：${esc(result.source||'策略数据契约')}</small></div></div>`;const m=result.metrics||{},flow=result.cashFlow||{},absolute=m.absoluteReturnPct??m.returnPct,audit=result.audit||{},auditText=audit.passed?'计算校验通过':'旧结果未完成新口径校验';return `<div class="panda-metrics"><div><small>策略累计收益率</small><strong class="${tone(absolute)}">${pct(absolute)}</strong></div><div><small>超额收益</small><strong class="${tone(m.excessReturnPct)}">${pct(m.excessReturnPct)}</strong></div><div><small>${esc(result.benchmarkName||'基准')}收益</small><strong class="${tone(m.benchmarkReturnPct)}">${pct(m.benchmarkReturnPct)}</strong></div><div><small>资金收益率</small><strong class="${tone(m.capitalReturnPct)}">${pct(m.capitalReturnPct)}</strong></div><div><small>最大回撤</small><strong class="${tone(m.maxDrawdownPct)}">${num(m.maxDrawdownPct)}%</strong></div><div><small>累计投入</small><strong>${money(flow.totalInvested)}</strong></div><div><small>累计收益</small><strong class="${tone(flow.netProfit)}">${signed(flow.netProfit)}</strong></div><div><small>期末金额</small><strong>${money(flow.endingValue)}</strong></div></div>${parameterMarkup}<div class="panda-chart-wrap">${chart(result)}<div class="panda-chart-legend"><span><i class="strategy"></i>策略累计收益率</span><span><i class="dash"></i>${esc(result.benchmarkName||'比较基准')}</span><span><i class="buy"></i>买入</span><span><i class="sell"></i>卖出</span></div></div><div class="panda-result-note"><b>${esc(auditText)}</b> · ${esc(audit.formula||'超额收益 = 策略同期累计收益率 - 同期基准收益率')}。区间：${esc(result.period?.start||'—')} 至 ${esc(result.period?.end||result.dataAsOf||'—')}。来源：${esc(result.source||'旧记录未保存来源')}。手续费：${flow.fees===null?'未计入，接口未返回完整历史费率':money(flow.fees)}。${flow.feeNote?esc(flow.feeNote)+' ':''}${esc(result.riskStatement||'历史回测不代表未来收益。')} 本结果是规则模拟，不是账户实际收益。</div><div class="panda-result-tabs"><strong>交易依据</strong><span>${result.trades?.length??'旧记录未保存明细'} 条</span></div>${tradesTable(result)}${allowPlan?`<div class="panda-save-row"><div><strong>保存为个人计划</strong><small>保存当前版本、标的、参数和回测引用；保存后仍需手动开启跟踪。</small></div>${button('保存计划','save-plan','','primary')}</div>`:''}`}
function detailBacktest(result){if(!result)return '<div class="panda-result-empty"><div><span class="result-mark">◌</span><strong>正在准备默认回测</strong><p>读取真实数据后在这里同步展示收益与曲线。</p></div></div>';if(result.status!=='ok')return `<div class="panda-result-blocked"><b>!</b><div><strong>暂无法判断</strong><p>${esc((result.missingData||[]).join('；')||'数据接口未返回完整结果。')}</p><small>来源：${esc(result.source||'策略数据契约')}</small></div></div>`;const m=result.metrics||{},flow=result.cashFlow||{},absolute=m.absoluteReturnPct??m.returnPct,audit=result.audit||{},auditText=audit.passed?'计算校验通过':'旧结果未完成新口径校验';return `<div class="panda-metrics"><div><small>策略累计收益率</small><strong class="${tone(absolute)}">${pct(absolute)}</strong></div><div><small>超额收益</small><strong class="${tone(m.excessReturnPct)}">${pct(m.excessReturnPct)}</strong></div><div><small>${esc(result.benchmarkName||'基准')}收益</small><strong class="${tone(m.benchmarkReturnPct)}">${pct(m.benchmarkReturnPct)}</strong></div><div><small>资金收益率</small><strong class="${tone(m.capitalReturnPct)}">${pct(m.capitalReturnPct)}</strong></div><div><small>最大回撤</small><strong class="${tone(m.maxDrawdownPct)}">${num(m.maxDrawdownPct)}%</strong></div><div><small>累计投入</small><strong>${money(flow.totalInvested)}</strong></div><div><small>累计收益</small><strong class="${tone(flow.netProfit)}">${signed(flow.netProfit)}</strong></div><div><small>期末金额</small><strong>${money(flow.endingValue)}</strong></div></div><div class="panda-chart-wrap">${chart(result)}<div class="panda-chart-legend"><span><i class="strategy"></i>策略累计收益率</span><span><i class="dash"></i>${esc(result.benchmarkName||'比较基准')}</span><span><i class="buy"></i>买入</span><span><i class="sell"></i>卖出</span></div></div><div class="panda-result-note"><b>${esc(auditText)}</b> · ${esc(audit.formula||'超额收益 = 策略同期累计收益率 - 同期基准收益率')}。区间：${esc(result.period?.start||'—')} 至 ${esc(result.period?.end||result.dataAsOf||'—')}。来源：${esc(result.source||'旧记录未保存来源')}。手续费：${flow.fees===null?'未计入，接口未返回完整历史费率':money(flow.fees)}。${flow.feeNote?esc(flow.feeNote)+' ':''}${esc(result.riskStatement||'历史回测不代表未来收益。')} 本结果是规则模拟，不是账户实际收益。</div>`}
function detailControls(result,parameterMarkup){const evidence=result?.status==='ok'?`<div class="panda-result-tabs"><strong>交易依据</strong><span>${result.trades?.length??'旧记录未保存明细'} 条</span></div><div class="panda-detail-evidence">${tradesTable(result)}</div><div class="panda-save-row"><div><strong>保存为个人计划</strong><small>保存当前版本、标的、参数和回测引用；保存后仍需手动开启跟踪。</small></div>${button('保存计划','save-plan','','primary')}</div>`:'<div class="panda-history-note">回测完成后，这里会列出每一次买卖及其触发依据。</div>';return `${parameterMarkup}${evidence}`}
function detail(item){const variant=currentVariant(item.id),params=state.result?.strategyId===item.id&&state.result.parameters?state.result.parameters:(variant?.params||item.defaultParams||{}),versions=state.variants.filter(x=>x.strategyId===item.id).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))),example=showcaseBest(item),code=state.result?.fundCode||variant?.fundCode||state.pendingCode||example?.fundCode||item.defaultFundCode||'',isDefault=(item.params||[]).every(spec=>String(params?.[spec.key]??'')===String(item.defaultParams?.[spec.key]??spec.default??'')),versionList=versions.map(v=>`<button class="panda-version-row" data-action="load-variant" data-id="${esc(v.id)}"><strong>${esc(v.name)} · 配置 v${v.version}</strong><small>${esc(v.fundCode||'固定基金池')} · ${esc(dt(v.updatedAt))} · 基于 Skill v${esc(v.baseVersion)}</small></button>`).join(''),versionPanel=versions.length?`<details class="panda-version-panel"><summary>个人配置版本 · ${versions.length}</summary><div class="panda-version-list">${versionList}</div></details>`:'',parameterMarkup=parameterModule(item,params,code,example,variant),resultTitle=state.defaultLoading===item.id?'正在计算默认回测':isDefault?'默认回测':'当前参数回测',resultMeta=state.result?.status==='ok'?`数据截至 ${esc(state.result.dataAsOf)} · ${esc(state.result.source)}`:'使用策略默认参数验证候选池，按超额收益选取案例';return `<div class="panda-detail-shell"><section class="panda-detail-left panda-detail-intro"><div class="panda-detail-titlebar"><button class="panda-back" data-action="back-library">← 返回策略</button><span class="strategy-badge">${esc(item.category)} · Skill v${esc(item.version)}</span></div><div class="panda-strategy-title"><h1>${esc(variant?.name||item.name)}</h1><p>${esc(item.description)}</p><div class="panda-explain-grid"><div><small>它怎么做</small><ul>${(item.rules||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div><small>适合谁</small><p>${esc(item.suitableFor)}</p></div><div><small>需要接受</small><p>${esc(item.tradeoff)}</p></div><div><small>数据口径</small><p>${esc(item.dataBasis)} · ${state.result?.period?`${esc(state.result.period.start)} 至 ${esc(state.result.period.end)}`:'进入后自动验证默认案例'}</p></div></div></div>${versionPanel}</section>${jobPanel()}<form id="panda-strategy-form" class="panda-parameter-section panda-detail-form"><div class="panda-detail-flow"><div><b>同一回测版本</b><span>右侧当前参数生成左侧收益、曲线和下方交易依据；重新回测后两侧同步更新。</span></div><em>参数配置&nbsp; → &nbsp;回测结果&nbsp; → &nbsp;交易依据</em></div><div class="panda-detail-workspace"><section class="panda-backtest-column"><div class="panda-column-head"><span>01</span><div><h3>${resultTitle}</h3><small>${resultMeta}</small></div></div>${detailBacktest(state.result)}</section><section class="panda-controls-column"><div class="panda-column-head"><span>02</span><div><h3>参数与交易依据</h3><small>查看本次配置；需要时修改参数并重新计算。</small></div></div>${detailControls(state.result,parameterMarkup)}</section></div></form></div>`}

function holdingsPage(){if(state.holdingsError)return `${heading('MY · ACCOUNT','我的持仓','读取同花顺爱基金当前真实持仓。')}<div class="panda-result-blocked"><b>!</b><div><strong>账户数据暂不可用</strong><p>${esc(state.holdingsError)}</p>${button('前往账户连接','nav','data-nav="account"','primary')}</div></div>`;if(!state.holdings)return `${heading('MY · ACCOUNT','我的持仓','正在读取真实账户数据。')}<div class="panda-loading"><i></i>正在查询同花顺爱基金…</div>`;const s=state.holdings.summary||{},funds=state.holdings.funds||[];return `${heading('MY · ACCOUNT','我的持仓','持仓、钱包与收益来自同花顺爱基金；组合历史分析使用扶摇复权净值。',button('刷新账户','refresh-holdings','','quiet'))}<div class="panda-plan-summary"><div><small>基金资产</small><strong>${money(s.totalAmount)}</strong></div><div><small>持有收益</small><strong class="${tone(s.holdIncome)}">${signed(s.holdIncome)}</strong></div><div><small>持仓数量</small><strong>${funds.length}</strong></div><div><small>数据来源</small><strong>同花顺</strong></div></div><div class="panda-holdings-layout"><section><div class="panda-section-head"><div><h2>持仓明细</h2><p>点击一只基金查看真实复权净值和策略入口。</p></div></div><div class="panda-holding-list">${funds.map(f=>`<button data-action="drill-fund" data-code="${esc(f.fundCode)}"><span><strong>${esc(f.fundName||f.fundCode)}</strong><small>${esc(f.fundCode)} · ${f.holdVol==='待确认'?'份额待确认':'已确认持仓'}</small></span><span><strong>${money(f.totalAmount)}</strong><small class="${tone(f.holdIncome)}">持有收益 ${signed(f.holdIncome)}</small></span></button>`).join('')||'<div class="panda-plan-empty">账户当前没有基金持仓。</div>'}</div></section><section>${portfolioPanel()}</section></div>`}
function alignComparison(primary,comparison){const bench=(comparison||[]).slice().sort((a,b)=>String(a.date).localeCompare(String(b.date)));let cursor=-1,current=null;return (primary||[]).map(row=>{while(cursor+1<bench.length&&String(bench[cursor+1].date)<=String(row.date)){cursor++;current=bench[cursor]}return {date:row.date,value:row.value,benchmark:current?.value??null}})}
function portfolioPanel(){if(state.analysisError)return `<div class="panda-result-blocked"><b>!</b><div><strong>组合分析暂不可用</strong><p>${esc(state.analysisError)}</p></div></div>`;if(!state.analysis)return '<div class="panda-loading"><i></i>正在计算持仓归因与风险…</div>';const a=state.analysis,m=a.metrics||{},aligned=alignComparison(a.history,a.benchmark);return `<div class="panda-section-head"><div><h2>持仓归因</h2><p>截至 ${esc(a.asOf)} · 当前权重历史模拟</p></div></div><div class="panda-metrics compact"><div><small>模拟收益</small><strong class="${tone(m.returnPct)}">${pct(m.returnPct)}</strong></div><div><small>最大回撤</small><strong class="${tone(m.maxDrawdownPct)}">${num(m.maxDrawdownPct)}%</strong></div><div><small>年化波动</small><strong>${num(m.volatilityPct)}%</strong></div><div><small>夏普</small><strong class="${tone(m.sharpe)}">${num(m.sharpe)}</strong></div></div><div class="panda-chart-wrap">${lineChart(aligned,Boolean(a.benchmark?.length))}<div class="panda-chart-legend"><span><i class="strategy"></i>组合模拟</span><span><i class="dash"></i>比较基准</span></div></div><div class="panda-allocation">${(a.allocations||[]).map(x=>`<div><span><i style="background:${esc(x.color)}"></i>${esc(x.name)} · ${x.funds} 只</span><strong>${num(x.percent)}%</strong></div>`).join('')}</div><div class="panda-result-note">${esc(a.method)}<br>来源：${esc(a.source)}</div>`}
function watchlistPage(){return `${heading('MY · LOCAL LIST','我的自选','自选是本地研究清单，不代表真实持仓。')}<form id="watch-form" class="panda-inline-form"><input name="code" pattern="[0-9]{6}" maxlength="6" placeholder="6 位基金代码" required><input name="name" maxlength="80" placeholder="基金名称（可选）"><button class="panda-button primary">添加自选</button></form><div class="panda-holding-list">${state.watchlist.map(x=>`<div class="panda-watch-row"><button data-action="drill-fund" data-code="${esc(x.code)}"><span><strong>${esc(x.name||x.code)}</strong><small>${esc(x.code)}</small></span></button><div>${button('用于策略','pick-for-strategy',`data-code="${esc(x.code)}"`,'quiet')}${button('移除','remove-watch',`data-code="${esc(x.code)}"`,'quiet')}</div></div>`).join('')||'<div class="panda-plan-empty">还没有自选基金。</div>'}</div>`}
function planCards(){return state.plans.map(plan=>{const signal=plan.latestSignal,label={draft:'草稿',active:'跟踪中',paused:'已暂停',archived:'已归档'}[plan.status]||plan.status,run=state.runs.find(x=>x.id===plan.backtestRunId),perf=plan.performance||(run?{totalInvested:run.cashFlow?.totalInvested,netProfit:run.cashFlow?.netProfit,returnPct:run.metrics?.absoluteReturnPct??run.metrics?.returnPct,benchmarkReturnPct:run.metrics?.benchmarkReturnPct,excessReturnPct:run.metrics?.excessReturnPct,dataAsOf:run.dataAsOf}:null),rate=n(perf?.returnPct),barWidth=Math.min(100,Math.abs(rate||0)*2);return `<article class="panda-plan-card"><div class="panda-plan-main"><div class="panda-plan-title"><strong>${esc(plan.name)}</strong><span class="panda-plan-status ${esc(plan.status)}">${label}</span></div><p>${esc(plan.fundCode||'行业基金池')} · ${esc(findStrategy(plan.strategyId)?.name||plan.strategyId)} · v${esc(plan.strategyVersion)}</p><small>回测数据截至 ${esc(plan.backtestDataAsOf||perf?.dataAsOf||'—')} · ${plan.lastCheckedAt?'最近检查 '+esc(dt(plan.lastCheckedAt)):'尚未检查'}</small></div><div class="panda-plan-signal"><strong>${esc(signal?.status==='ok'?(signal.state||'等待新信号'):'暂无法判断')}</strong><small>${esc(signal?.dataAsOf?'数据日期 '+signal.dataAsOf:'等待首次检查')}</small><em>${esc(signal?.reason||(signal?.missingData||[])[0]||'启用跟踪后检查最新状态')}</em></div><div class="panda-plan-actions">${plan.status==='draft'?button('开启跟踪','plan-action',`data-id="${plan.id}" data-plan-action="enable"`,'primary'):''}${plan.status==='active'?button('立即检查','plan-action',`data-id="${plan.id}" data-plan-action="check"`,'quiet')+button('暂停','plan-action',`data-id="${plan.id}" data-plan-action="pause"`,'quiet'):''}${plan.status==='paused'?button('恢复','plan-action',`data-id="${plan.id}" data-plan-action="enable"`,'primary'):''}${plan.status!=='archived'?button('归档','plan-action',`data-id="${plan.id}" data-plan-action="archive"`,'quiet'):''}</div><div class="panda-plan-performance"><div class="panda-plan-performance-head"><small>关联回测快照 · 不代表账户实际收益</small><span>${perf?'数据截至 '+esc(perf.dataAsOf||plan.backtestDataAsOf||'—'):'暂无可追溯结果'}</span></div><div class="panda-plan-kpis"><span>模拟累计投入 <b>${money(perf?.totalInvested)}</b></span><span>模拟累计收益 <b class="${tone(perf?.netProfit)}">${signed(perf?.netProfit)}</b></span><span>策略累计收益 <b class="${tone(rate)}">${pct(rate)}</b></span><span>同期基准收益 <b class="${tone(perf?.benchmarkReturnPct)}">${pct(perf?.benchmarkReturnPct)}</b></span><span>超额收益 <b class="${tone(perf?.excessReturnPct)}">${pct(perf?.excessReturnPct)}</b></span></div><div class="panda-plan-formula">${esc(perf?.formula||'超额收益 = 策略同期累计收益率 - 同期基准收益率')}</div><div class="panda-return-bar"><i class="${tone(rate)}" style="width:${barWidth}%"></i></div></div></article>`}).join('')||'<div class="panda-plan-empty">还没有策略计划。</div>'}
function plansPage(){return `${heading('MY PLANS','我的计划',state.planPerformanceLoading?'正在补齐旧计划的基准和超额收益…':'保存、启用、暂停和归档策略计划；信号在应用运行期间每 30 分钟检查。')}<div class="panda-plan-list">${planCards()}</div>`}
function historyPage(){return `${heading('RUN HISTORY','运行历史','每条记录均可打开回看指标、参数、曲线、交易位置和数据口径。')}<div class="panda-history-list">${state.runs.slice().reverse().map(run=>{const value=run.metrics?.absoluteReturnPct??run.metrics?.returnPct;return `<button class="panda-run-card" data-action="open-run" data-id="${esc(run.id)}"><div><strong>${esc(findStrategy(run.strategyId)?.name||run.strategyId)}</strong><small>${esc(run.fundCode||'行业基金池')} · Skill v${esc(run.strategyVersion)} · ${esc(dt(run.createdAt))}</small></div><div class="panda-run-result"><strong class="${tone(value)}">${run.status==='ok'?pct(value):'暂无法判断'}</strong><small>${esc(run.dataAsOf?'数据截至 '+run.dataAsOf:(run.missingData||[]).join('；'))}</small></div><span>查看回测 →</span></button>`}).join('')||'<div class="panda-plan-empty">还没有回测记录。</div>'}</div>`}
function accountPage(){const connected=Boolean(state.holdings),status=state.accountBusy?'正在等待扫码确认…':connected?`账户已连接，当前读取到 ${(state.holdings.funds||[]).length} 只基金持仓。`:state.holdingsError||'尚未取得账户数据。',disabled=state.accountBusy?'disabled':'',action=connected?button('切换账户','switch-account',disabled,state.accountBusy?'quiet':'primary'):button('扫码连接账户','login-fund',disabled,state.accountBusy?'quiet':'primary');return `${heading('ACCOUNT · READ ONLY','账户与连接','连接同花顺爱基金后，Agent 可在单个会话授权范围内只读查询持仓和订单。')}<div class="panda-connect-grid"><section><span>◎</span><h2>同花顺爱基金</h2><p>${esc(status)}</p><div class="panda-account-actions">${action}${connected?button('刷新账户','refresh-holdings',disabled,'quiet'):''}</div></section><section><span>▣</span><h2>权限边界</h2><p>切换账户会替换本机当前同花顺授权；Agent 仍只能查询、研究和管理本地计划，不会提交申购、赎回、撤单或支付。</p></section></div>`}
function modelRows(){const value=D.status?.models;return Array.isArray(value?.data)?value.data:Array.isArray(value?.models)?value.models:[]}
function settingsPage(){if(!D.enabled)return `${heading('MODEL SETTINGS','模型与推理设置','真实模型设置只在 Electron 桌面应用中提供。')}<div class="panda-result-blocked"><b>!</b><div><strong>当前是浏览器模式</strong><p>请运行 start-desktop.command 使用持续会话、模型选择、思考强度和工具进度。</p></div></div>`;const models=modelRows(),settings=D.settings||{},selected=settings.subscriptionModel||'gpt-6-astra',model=models.find(x=>x.id===selected),efforts=(model?.supportedReasoningEfforts||[]).map(x=>typeof x==='string'?x:x?.reasoningEffort).filter(Boolean);return `${heading('MODEL SETTINGS','模型与推理设置','新会话使用这里选择的模型和思考强度；已有会话保持创建时的设置。')}<form id="model-form" class="panda-settings-card"><div class="panda-field"><label>订阅模型</label><select name="model">${(models.length?models:[{id:selected,displayName:selected}]).map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.displayName||x.id)}</option>`).join('')}</select></div><div class="panda-field"><label>思考强度</label><select name="effort">${(efforts.length?efforts:['low','medium','high','xhigh']).map(x=>`<option value="${x}" ${x===settings.subscriptionEffort?'selected':''}>${esc(({low:'低',medium:'中',high:'高',xhigh:'很高',max:'最高',ultra:'超高'})[x]||x)}</option>`).join('')}</select></div><div class="panda-detail-actions"><button class="panda-button primary">保存到新会话</button></div></form>`}

function render(){const content=$('#panda-content'),shell=$('#agent-shell');if(shell&&content.contains(shell))$('#agent-panel').append(shell);let html;if(state.selected)html=detail(findStrategy(state.selected));else html=({workbench:home,library,holdings:holdingsPage,watchlist:watchlistPage,plans:plansPage,history:historyPage,account:accountPage,settings:settingsPage}[state.nav]||home)();content.innerHTML=html;document.querySelectorAll('.panda-sidebar [data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===state.nav));$('#panda-data-status').textContent=state.holdings?'真实账户与行情已连接':`已载入 ${state.catalog.length} 个策略`;ensureChrome();placeAgent();renderSessions();if(state.nav==='holdings'&&!state.holdings&&!state.holdingsError)loadHoldings()}
function ensureChrome(){if(!$('#panda-toast'))document.body.insertAdjacentHTML('beforeend','<div id="panda-toast" class="panda-toast"></div>')}
function placeAgent(){const shell=$('#agent-shell'),panel=$('#agent-panel'),conversationHost=$('#agent-conversation-host'),composerHost=$('#agent-composer-host');if(!shell||!panel)return;document.body.classList.remove('panda-agent-side','panda-conversation-active','panda-conversation-idle');panel.hidden=true;if(state.nav==='workbench'&&!state.selected&&(conversationHost||composerHost)){(conversationHost||composerHost).append(shell);document.body.classList.add(conversationHost?'panda-conversation-active':'panda-conversation-idle')}else panel.append(shell);renderAgentPanel()}

function textFromUserContent(content){return (content||[]).filter(x=>x.type==='text'&&!String(x.text||'').startsWith('[WORKBENCH_PAGE_CONTEXT]')).map(x=>x.text||'').join('\n')}
function reasoningText(item){for(const v of [item?.text,item?.summaryText,item?.summary]){if(typeof v==='string'&&v.trim())return v;if(Array.isArray(v)){const t=v.map(x=>typeof x==='string'?x:x?.text||'').filter(Boolean).join('\n');if(t)return t}}return ''}
function planText(plan){const rows=Array.isArray(plan)?plan:Array.isArray(plan?.steps)?plan.steps:[];return rows.map(x=>`${x.status==='completed'?'✓':x.status==='inProgress'||x.status==='in_progress'?'◌':'○'} ${x.step||x.text||x.description||''}`).join('\n')}
function renderAgentItem(m){if(m.type==='tool')return `<div class="agent-tool ${m.status==='failed'?'error':''}"><span>${['inProgress','running'].includes(m.status)?'<i class="spinner"></i>':'◇'}</span><div><strong>${esc(toolLabel(m.tool))}</strong><small>${m.status==='completed'?'工具已完成':m.status==='failed'?'工具调用失败':'正在调用真实工具'}</small></div></div>`;if(m.type==='reasoning')return `<details class="agent-reasoning" open><summary>${m.streaming?'正在形成推理摘要…':'推理摘要'}</summary><div>${renderMarkdown(m.text)}</div></details>`;if(m.type==='plan')return `<div class="agent-plan"><strong>执行计划</strong>${renderMarkdown(m.text)}</div>`;return `<div class="agent-message ${m.role} ${m.error?'error':''}"><small>${m.role==='user'?'你':'◆ ParadoxAI'}</small><div>${m.role==='assistant'?renderMarkdown(m.text):esc(m.text).replaceAll('\n','<br>')}</div></div>`}
function agentProgressMarkup(){if(D.pendingInput)return '<div class="agent-progress-track waiting"><span class="done">理解问题</span><span class="done">规划与工具</span><span class="current">等待补充</span><em>需要你的信息</em></div>';if(!D.running)return `<div class="agent-progress-track idle"><span class="done">会话已就绪</span><em>${D.current?'可继续追问':'发送消息后开始'}</em></div>`;const hasTool=[...D.tools.values()].length>0,hasAnswer=D.messages.some(x=>x.role==='assistant'&&x.text),stage=hasAnswer?2:hasTool?1:0,elapsed=D.turnStartedAt?Math.max(0,Math.floor((Date.now()-D.turnStartedAt)/1000)):0;return `<div class="agent-progress-track"><span class="${stage>0?'done':'current'}">理解与推理</span><span class="${stage>1?'done':stage===1?'current':''}">调用工具</span><span class="${stage===2?'current':''}">生成回答</span><em id="agent-elapsed">${elapsed} 秒</em></div>`}
function toolLabel(name){return ({list_investment_strategies:'读取投资策略目录',run_investment_backtest:'运行真实策略回测',save_strategy_variant:'保存策略版本',get_account_brief:'读取账户简报',list_holdings:'读取真实持仓',analyze_portfolio:'分析持仓归因',list_orders:'查询真实订单',list_watchlist:'读取自选基金',set_watchlist:'更新自选基金',get_fund_accounts:'读取基金账户'})[name]||name||'基金工具'}
function renderSessions(){const host=$('#panda-sessions');if(!host)return;host.innerHTML=D.enabled?(D.sessions.map(s=>`<div class="panda-session-row ${s.threadId===D.current?.threadId?'active':''}"><button data-session="${esc(s.threadId)}" ${D.running?'disabled':''}><strong>${s.pinned?'★ ':''}${esc(s.title)}</strong><small>${esc(s.model||s.providerName||'Codex')} · ${esc(String(s.updatedAt||'').slice(5,16).replace('T',' '))}</small></button><button data-session-pin="${esc(s.threadId)}" title="${s.pinned?'取消置顶':'置顶'}" ${D.running?'disabled':''}>${s.pinned?'★':'☆'}</button><button data-session-delete="${esc(s.threadId)}" title="删除对话" ${D.running?'disabled':''}>×</button></div>`).join('')||'<span>还没有会话</span>'):'<span>浏览器模式不启动模型会话</span>'}
function renderAgentQuestion(){const host=$('#agent-question');if(!host)return;const request=D.pendingInput;if(!request){host.hidden=true;host.innerHTML='';return}host.hidden=false;host.innerHTML=`<form id="agent-question-form"><strong>Agent 需要你补充信息</strong>${(request.questions||[]).map((q,i)=>{const opts=(q.options||[]).map((o,j)=>`<label><input type="radio" name="answer-${i}" value="${esc(o.label)}" ${j===0?'required':''}><span><b>${esc(o.label)}</b><small>${esc(o.description||'')}</small></span></label>`).join('');return `<fieldset data-id="${esc(q.id)}"><legend>${esc(q.header||'请确认')}</legend><p>${esc(q.question)}</p>${opts||`<input name="answer-${i}" required>`}</fieldset>`}).join('')}<button class="panda-button primary">提交回答</button></form>`}
function renderAgentPanel(){if(!D.enabled){if($('#agent-provider'))$('#agent-provider').textContent='桌面 Agent 未启动';if($('#agent-status'))$('#agent-status').textContent='当前仅预览界面';if($('#agent-messages'))$('#agent-messages').innerHTML='<div class="agent-empty"><span>◆</span><strong>浏览器模式不运行模型</strong><p>启动 Electron 版即可使用真实模型、持续会话、推理摘要和工具进度。</p></div>';if($('#agent-input'))$('#agent-input').disabled=true;if($('#agent-send'))$('#agent-send').disabled=true;return}const provider=D.current?.providerName||(D.settings?.activeMode==='subscription'?'ChatGPT / Codex 订阅':'API 模型'),model=D.current?.model||D.settings?.subscriptionModel,effort=D.current?.effort||D.settings?.subscriptionEffort;if($('#agent-provider'))$('#agent-provider').textContent=`${provider||'模型服务'}${model?' · '+model:''}${effort?' · '+effort+' 推理':''}`;if($('#panda-model-status'))$('#panda-model-status').textContent=model||'待连接';if($('#agent-status'))$('#agent-status').innerHTML=agentProgressMarkup();const live=D.running?'<div class="agent-live-feedback"><i class="spinner"></i><div><strong>ParadoxAI 正在处理</strong><small>模型提供的推理摘要、执行计划和工具调用会依次显示在这里。</small></div></div>':'';if($('#agent-messages'))$('#agent-messages').innerHTML=D.messages.length?D.messages.map(renderAgentItem).join('')+live:'<div class="agent-empty"><span>◆</span><strong>开始一个基金研究任务</strong><p>例如：分析我的真实持仓，推荐一种操作较少的策略，然后用真实数据回测。</p></div>';renderAgentQuestion();if($('#agent-run-state'))$('#agent-run-state').textContent=D.running?'运行中':'就绪';if($('#agent-stop'))$('#agent-stop').hidden=!D.running;if($('#agent-send'))$('#agent-send').disabled=D.running;if($('#agent-input'))$('#agent-input').disabled=D.running;if($('#agent-data-consent')){$('#agent-data-consent').checked=Boolean(D.current?.dataAuthorized);$('#agent-data-consent').disabled=Boolean(D.current?.dataAuthorized)||D.running}if($('#agent-pin')){$('#agent-pin').textContent=D.current?.pinned?'★':'☆';$('#agent-pin').disabled=!D.current||D.running}if($('#agent-rename'))$('#agent-rename').disabled=!D.current||D.running;if($('#agent-archive'))$('#agent-archive').disabled=!D.current||D.running;if($('#agent-delete'))$('#agent-delete').disabled=!D.current||D.running;requestAnimationFrame(()=>{const m=$('#agent-messages');if(m)m.scrollTop=m.scrollHeight})}
function hydrateThread(thread){D.messages=[];D.tools.clear();D.pendingInput=null;for(const turn of thread?.turns||[])for(const item of turn.items||[]){if(item.type==='userMessage')D.messages.push({id:item.id,role:'user',text:textFromUserContent(item.content)});else if(item.type==='agentMessage'&&item.text&&!/^Reconnecting/.test(item.text))D.messages.push({id:item.id,role:'assistant',text:item.text});else if(item.type==='reasoning'&&reasoningText(item))D.messages.push({id:item.id,type:'reasoning',text:reasoningText(item)});else if(item.type==='mcpToolCall'){const row={id:item.id,type:'tool',tool:item.tool,status:item.status,error:item.error};D.messages.push(row);D.tools.set(item.id,row)}}renderAgentPanel()}
async function newSession(){const r=await desktopCall(window.fundDesktop.newSession());D.current=r.session;D.messages=[];D.sessions=await desktopCall(window.fundDesktop.listSessions());state.nav='workbench';state.selected=null;render();$('#agent-input')?.focus()}
async function resumeSession(id){const r=await desktopCall(window.fundDesktop.resumeSession(id));if(r.stale){D.sessions=r.sessions||[];D.current=null;D.messages=[];render();return}D.current=r.session;hydrateThread(r.thread);renderSessions();renderAgentPanel()}
function pageContext(){const c={route:state.nav,pageTitle:titles[state.nav]||'策略详情'};if(state.selected){const item=findStrategy(state.selected);c.strategy={id:item.id,name:item.name,version:item.version};if(state.result)c.backtest={status:state.result.status,fundCode:state.result.fundCode,dataAsOf:state.result.dataAsOf}}if(state.drill)c.selectedFund={code:state.drill.code,name:state.drill.name};return c}
function onAgentEvent({method,params}){if(params?.threadId&&params.threadId!==D.current?.threadId)return;if(method==='turn/started'){D.running=true;D.turnStartedAt=D.turnStartedAt||Date.now()}else if(method==='turn/completed'){D.running=false;D.pendingInput=null;D.turnStartedAt=null;window.fundDesktop.listSessions().then(desktopCall).then(x=>{D.sessions=x;D.current=x.find(s=>s.threadId===D.current?.threadId)||D.current;renderSessions();renderAgentPanel()}).catch(()=>{})}else if(method==='item/tool/requestUserInput')D.pendingInput=params;else if(method==='item/tool/requestUserInput/resolved')D.pendingInput=null;else if(method==='item/agentMessage/delta'){let row=D.messages.find(x=>x.id===params.itemId);if(!row){row={id:params.itemId,role:'assistant',text:''};D.messages.push(row)}row.text+=params.delta||''}else if(method==='item/reasoning/summaryTextDelta'){let row=D.messages.find(x=>x.id===params.itemId);if(!row){row={id:params.itemId,type:'reasoning',text:'',streaming:true};D.messages.push(row)}row.text+=params.delta||''}else if(method==='item/completed'&&params.item?.type==='reasoning'){const text=reasoningText(params.item);let row=D.messages.find(x=>x.id===params.item.id);if(!row&&text)D.messages.push({id:params.item.id,type:'reasoning',text});else if(row){row.text=text||row.text;row.streaming=false}}else if(method==='turn/plan/updated'){let row=D.messages.find(x=>x.type==='plan'&&x.turnId===params.turnId);if(!row){row={id:'plan-'+Date.now(),turnId:params.turnId,type:'plan',text:planText(params.plan)};D.messages.push(row)}else row.text=planText(params.plan)}else if(method==='item/started'&&params.item?.type==='mcpToolCall'){const row={id:params.item.id,type:'tool',tool:params.item.tool,status:params.item.status};D.messages.push(row);D.tools.set(row.id,row)}else if(method==='item/completed'&&params.item?.type==='mcpToolCall'){const row=D.tools.get(params.item.id);if(row)Object.assign(row,{status:params.item.status,error:params.item.error})}else if(method==='item/completed'&&params.item?.type==='agentMessage'){let row=D.messages.find(x=>x.id===params.item.id);if(!row)D.messages.push({id:params.item.id,role:'assistant',text:params.item.text||''});else row.text=params.item.text||row.text}else if(method==='error'){D.running=false;D.turnStartedAt=null;D.messages.push({role:'assistant',text:params.error?.message||params.message||'Agent 运行失败。',error:true})}renderAgentPanel()}
async function sendAgent(text){if(!D.enabled){toast('真实 Agent 需要从桌面应用启动。');return}if(!text||D.running)return;if(!D.current)await newSession();const consent=D.current.dataAuthorized||Boolean($('#agent-data-consent')?.checked),context=pageContext();D.messages.push({id:'local-'+Date.now(),role:'user',text});D.running=true;D.turnStartedAt=Date.now();render();await desktopCall(window.fundDesktop.sendMessage({threadId:D.current.threadId,text,authorizeAccountData:consent,pageContext:context}));D.current.dataAuthorized=consent;if($('#agent-input'))$('#agent-input').value=''}
async function initDesktop(){if(!D.enabled)return;window.fundDesktop.onEvent(onAgentEvent);window.fundDesktop.onBusinessChanged(async()=>{await refreshLocal();render()});D.settings=await desktopCall(window.fundDesktop.getSettings());D.sessions=await desktopCall(window.fundDesktop.listSessions());try{D.status=await desktopCall(window.fundDesktop.getStatus())}catch(e){D.status={error:e.message}}D.initialized=true;if(D.sessions.length)await resumeSession(D.sessions[0].threadId);else render()}

async function loadHoldings(){state.holdingsError='';try{state.holdings=await api('/api/holdings');render();try{state.analysis=await api('/api/portfolio-analysis')}catch(e){state.analysisError=e.message}render()}catch(e){state.holdingsError=e.message;render()}}
async function refreshLocal(){const b=await api('/api/bootstrap');state.csrf=b.csrf;state.catalog=b.strategyCatalog||[];state.plans=b.state?.strategyPlans||[];state.runs=b.state?.strategyRuns||[];state.events=b.state?.strategyEvents||[];state.variants=b.state?.strategyVariants||[];state.watchlist=b.state?.watchlist||[]}
async function loadShowcase(item){if(state.showcases[item.id])return state.showcases[item.id];if(showcasePromises.has(item.id))return showcasePromises.get(item.id);state.showcaseLoading.add(item.id);render();const promise=api('/api/strategy-invest/showcase',{strategyId:item.id}).then(async report=>{state.showcases[item.id]=report;state.runs=await api('/api/strategy-runs');return report}).finally(()=>{state.showcaseLoading.delete(item.id);showcasePromises.delete(item.id);render()});showcasePromises.set(item.id,promise);return promise}
async function loadShowcases(){for(const item of state.catalog){try{await loadShowcase(item)}catch(e){state.showcases[item.id]={status:'blocked',missingData:[e.message]}}}render()}
async function runBacktest(item,code,params,isDefault=false){state.busy=true;state.defaultLoading=isDefault?item.id:null;state.result=null;state.job={status:'running',stage:'queued',progress:1,logs:[{at:new Date().toISOString(),message:isDefault?'正在按策略卡相同参数准备默认回测。':'正在按当前参数准备回测。'}]};render();try{const created=await api('/api/strategy-invest/jobs',{strategyId:item.id,code:String(code||'').trim(),params});await pollJob(created.jobId)}catch(e){state.busy=false;state.defaultLoading=null;state.job={status:'failed',stage:'failed',progress:100,error:e.message,logs:[{at:new Date().toISOString(),message:e.message}]};render()}}
async function startBacktest(form,item){const {raw,params}=paramsFromForm(form,item);await runBacktest(item,raw.code,params,false)}
async function openStrategy(id){const item=findStrategy(id);state.selected=id;state.variant=null;state.result=null;state.job=null;state.detailTab='editor';state.paramEditing=false;state.paramsExpanded=false;state.defaultLoading=item.id;render();try{const report=await loadShowcase(item),best=report?.best||showcaseBest(item);state.defaultLoading=null;if(best?.status==='ok'){state.result=best;render();return}state.result={status:'blocked',strategyId:item.id,strategyVersion:item.version,missingData:report?.missingData||['候选池没有通过数据校验的结果。'],source:item.dataBasis};render()}catch(e){state.defaultLoading=null;state.result={status:'blocked',strategyId:item.id,strategyVersion:item.version,missingData:[e.message],source:item.dataBasis};render()}}
async function pollJob(id){clearTimeout(jobTimer);try{const job=await api('/api/strategy-invest/job?id='+encodeURIComponent(id));state.job=job;if(job.status==='completed'){state.busy=false;state.defaultLoading=null;state.paramEditing=false;state.result=job.result;state.runs=await api('/api/strategy-runs');render();return}if(job.status==='failed'){state.busy=false;state.defaultLoading=null;render();return}render();jobTimer=setTimeout(()=>pollJob(id),450)}catch(e){state.busy=false;state.defaultLoading=null;toast(e.message);render()}}
async function saveVariant(form,item){const {raw,params}=paramsFromForm(form,item);const saved=await api('/api/strategy-variants',{id:raw.variantId||undefined,strategyId:item.id,name:raw.name,description:raw.description,code:raw.code,params});state.variants=await api('/api/strategy-variants');state.variant=saved;state.paramEditing=false;toast(`已保存配置 v${saved.version}`);render()}
async function savePlan(){if(state.result?.status!=='ok')return;const item=findStrategy(state.selected),target=state.result.fundCode||'行业基金池';await api('/api/strategy-plans',{strategyId:item.id,code:state.result.fundCode,fundPool:state.result.fundPool,amount:state.result.parameters?.amount??state.result.parameters?.initial_capital,params:state.result.parameters,name:`${currentVariant(item.id)?.name||item.name} · ${target}`,runId:state.result.runId,dataAsOf:state.result.dataAsOf});state.plans=await api('/api/strategy-plans');toast('已保存为计划草稿');render()}
async function planAction(id,action){await api('/api/strategy-plans/action',{id,action});state.plans=await api('/api/strategy-plans');render()}
async function refreshPlanPerformance(){if(state.planPerformanceLoading||!state.plans.some(plan=>n(plan.performance?.excessReturnPct)===null||n(plan.performance?.benchmarkReturnPct)===null))return;state.planPerformanceLoading=true;render();try{state.plans=await api('/api/strategy-plans/refresh-performance',{});state.runs=await api('/api/strategy-runs')}catch(e){toast(e.message)}finally{state.planPerformanceLoading=false;render()}}
async function checkPlans(){if(!state.plans.some(x=>x.status==='active'))return;try{await api('/api/strategy-plans/check-all',{});state.plans=await api('/api/strategy-plans');if(state.nav==='plans')render()}catch{}}
function startMonitor(){clearInterval(planMonitorTimer);checkPlans();planMonitorTimer=setInterval(checkPlans,30*60*1000)}
async function openRun(id){const run=state.runs.find(x=>x.id===id);if(!run)return;const result=run.result||{status:run.status,strategyId:run.strategyId,strategyVersion:run.strategyVersion,fundCode:run.fundCode,dataAsOf:run.dataAsOf,period:run.period,parameters:run.parameters,metrics:run.metrics,cashFlow:run.cashFlow,benchmarkName:run.benchmarkName,source:run.source,missingData:run.missingData,trades:null},dialog=$('#panda-dialog'),host=$('#panda-dialog-content'),params=Object.entries(result.parameters||{}).map(([key,value])=>`<span><b>${esc(key)}</b>${esc(value)}</span>`).join('');host.innerHTML=`<div class="panda-dialog-head"><div><small>BACKTEST REVIEW · ${esc(run.id)}</small><h2>${esc(findStrategy(run.strategyId)?.name||run.strategyId)}</h2><p>${esc(run.fundCode||'行业基金池')} · Skill v${esc(run.strategyVersion)} · ${esc(dt(run.createdAt))}</p></div><button data-action="close-dialog">×</button></div><div class="panda-run-params">${params||'<span>旧记录未保存参数</span>'}</div><div class="panda-dialog-result">${resultView(result,false)}</div>`;dialog.showModal()}
async function drillFund(code){const dialog=$('#panda-dialog'),host=$('#panda-dialog-content');host.innerHTML='<div class="panda-loading"><i></i>正在读取真实复权净值…</div>';dialog.showModal();try{const d=await api('/api/fund/nav?code='+encodeURIComponent(code));state.drill=d;host.innerHTML=`<div class="panda-dialog-head"><div><small>FUND DRILLDOWN</small><h2>${esc(d.name)}</h2><p>${esc(d.code)} · 数据截至 ${esc(d.dataAsOf)} · ${esc(d.source)}</p></div><button data-action="close-dialog">×</button></div><div class="panda-chart-wrap">${lineChart(d.points)}</div><div class="panda-result-note">基金经理：${esc(d.manager||'接口未提供')}。曲线展示复权净值累计变化，不代表个人账户收益。</div><div class="panda-detail-actions">${button('带入策略回测','pick-for-strategy',`data-code="${esc(code)}"`,'primary')}</div>`}catch(e){host.innerHTML=`<div class="panda-result-blocked"><b>!</b><div><strong>下钻失败</strong><p>${esc(e.message)}</p></div></div>`}}
function accountLoginMarkup(force,confirm=false){const title=force?'切换同花顺账户':'连接同花顺账户',desc=force?'扫码成功后，本机当前授权会替换为新账户。策略、回测和本地计划不会被删除。':'使用同花顺 App 扫描官方授权页二维码，并在手机上确认授权。';return `<div class="panda-dialog-head"><div><small>THS ACCOUNT · QR AUTH</small><h2>${title}</h2><p>${desc}</p></div><button data-action="close-dialog">×</button></div><div class="panda-login-body"><div class="panda-login-visual"><div class="panda-phone-mark"><i></i><b>⌁</b></div><span>${confirm?'准备重新授权':'二维码显示在已打开的官方授权页'}</span></div><div class="panda-login-copy"><ol><li>打开手机同花顺 App</li><li>扫描浏览器官方授权页中的二维码</li><li>在手机上确认后等待本页自动更新</li></ol><div id="panda-login-status" class="panda-login-status ${confirm?'warning':'running'}"><i></i><span>${confirm?'确认后将强制发起新账号扫码授权。':esc(state.accountLoginMessage||'正在打开官方授权页…')}</span></div><p>工作台不会读取二维码内容、登录凭据、完整账户号或银行卡号。</p></div></div><div class="panda-login-footer">${confirm?`${button('取消','close-dialog','','quiet')}${button('开始扫码切换','confirm-switch-account','','primary')}`:button('关闭窗口','close-dialog','','quiet')}</div>`}
function showAccountLoginDialog(force,confirm=false){const dialog=$('#panda-dialog'),host=$('#panda-dialog-content');host.innerHTML=accountLoginMarkup(force,confirm);if(!dialog.open)dialog.showModal()}
function updateAccountLoginDialog(message,status='running'){const node=$('#panda-login-status');if(!node)return;node.className=`panda-login-status ${status}`;node.innerHTML=`<i></i><span>${esc(message)}</span>`}
async function loginFund(force=false){state.accountBusy=true;state.accountLoginMode=force?'switch':'login';state.accountLoginMessage='正在打开官方授权页…';render();showAccountLoginDialog(force);try{const started=await api('/api/fund/login',{force});state.accountLoginMessage=started.message;updateAccountLoginDialog(started.message);pollLogin()}catch(e){state.accountBusy=false;state.accountLoginMessage=e.message;updateAccountLoginDialog(e.message,'failed');toast(e.message);render()}}
async function pollLogin(){try{const r=await api('/api/fund/login-status');state.accountLoginMessage=r.message;if(r.running){updateAccountLoginDialog(r.message);setTimeout(pollLogin,2200);return}state.accountBusy=false;updateAccountLoginDialog(r.message,r.success?'success':'failed');toast(r.message);if(r.success){state.holdings=null;state.holdingsError='';state.analysis=null;render();loadHoldings()}else render()}catch(e){state.accountBusy=false;state.accountLoginMessage=e.message;updateAccountLoginDialog(e.message,'failed');toast(e.message);render()}}

document.addEventListener('click',async e=>{const t=e.target.closest('[data-action],[data-nav],[data-session],[data-session-pin],[data-session-delete]');if(!t)return;try{if(t.dataset.nav){state.nav=t.dataset.nav;state.selected=null;state.result=null;render();if(state.nav==='plans')refreshPlanPerformance();return}if(t.dataset.session){await resumeSession(t.dataset.session);state.nav='workbench';state.selected=null;render();return}if(t.dataset.sessionPin){const row=D.sessions.find(x=>x.threadId===t.dataset.sessionPin);D.sessions=await desktopCall(window.fundDesktop.updateSession({threadId:row.threadId,pinned:!row.pinned}));D.current=D.sessions.find(x=>x.threadId===D.current?.threadId)||D.current;renderSessions();return}if(t.dataset.sessionDelete){await deleteSession(t.dataset.sessionDelete);return}const a=t.dataset.action;if(a==='open-strategy')await openStrategy(t.dataset.id);else if(a==='open-run')await openRun(t.dataset.id);else if(a==='back-library'){state.selected=null;state.variant=null;state.result=null;state.nav='library';render()}else if(a==='edit-params'){state.paramEditing=true;render()}else if(a==='cancel-param-edit'){state.paramEditing=false;render()}else if(a==='toggle-params'){state.paramsExpanded=!state.paramsExpanded;render()}else if(a==='load-variant'){state.variant=state.variants.find(x=>x.id===t.dataset.id);state.result=null;state.job=null;state.paramEditing=true;state.paramsExpanded=true;render()}else if(a==='save-plan')await savePlan();else if(a==='plan-action')await planAction(t.dataset.id,t.dataset.planAction);else if(a==='refresh-holdings'){state.holdings=null;state.analysis=null;render();loadHoldings()}else if(a==='drill-fund')await drillFund(t.dataset.code);else if(a==='close-dialog')$('#panda-dialog').close();else if(a==='remove-watch'){const b=await api('/api/watchlist',{code:t.dataset.code,remove:true});state.watchlist=b.watchlist||[];render()}else if(a==='pick-for-strategy'){state.pendingCode=t.dataset.code;state.nav='library';state.selected=null;$('#panda-dialog')?.close();render();toast(`已选择基金 ${t.dataset.code}，打开策略即可回测。`)}else if(a==='login-fund')await loginFund(false);else if(a==='switch-account')showAccountLoginDialog(true,true);else if(a==='confirm-switch-account')await loginFund(true)}catch(err){toast(err.message)}});
document.addEventListener('submit',async e=>{e.preventDefault();try{if(e.target.id==='panda-strategy-form'){const item=findStrategy(state.selected),intent=e.submitter?.value||'run';if(intent==='save')await saveVariant(e.target,item);else await startBacktest(e.target,item)}else if(e.target.id==='watch-form'){const raw=Object.fromEntries(new FormData(e.target)),b=await api('/api/watchlist',{code:raw.code,name:raw.name});state.watchlist=b.watchlist||[];render()}else if(e.target.id==='model-form'){const raw=Object.fromEntries(new FormData(e.target));D.settings=await desktopCall(window.fundDesktop.saveProvider({mode:'subscription',model:raw.model,effort:raw.effort}));toast('模型设置已保存，将用于新会话');render()}else if(e.target.id==='agent-form'){await sendAgent($('#agent-input').value.trim())}else if(e.target.id==='agent-question-form'){const request=D.pendingInput,form=new FormData(e.target),answers={};for(const [i,q] of (request.questions||[]).entries()){const value=String(form.get(`answer-${i}`)||'').trim();if(!value)throw new Error('请回答全部问题。');answers[q.id]={answers:[value]}}await desktopCall(window.fundDesktop.answerUserInput({requestId:request.requestId,answers}));D.pendingInput=null;renderAgentPanel()}}catch(err){toast(err.message)}});
document.addEventListener('change',e=>{if(e.target?.name!=='model'||e.target.form?.id!=='model-form')return;const model=modelRows().find(x=>x.id===e.target.value),efforts=(model?.supportedReasoningEfforts||[]).map(x=>typeof x==='string'?x:x?.reasoningEffort).filter(Boolean),select=e.target.form.elements.effort,current=select.value;select.innerHTML=(efforts.length?efforts:['low','medium','high','xhigh']).map(x=>`<option value="${esc(x)}" ${x===current?'selected':''}>${esc(({low:'低',medium:'中',high:'高',xhigh:'很高',max:'最高',ultra:'超高'})[x]||x)}</option>`).join('');if(!efforts.includes(current)&&efforts.length)select.value=efforts[0]});
$('#agent-new').addEventListener('click',()=>D.enabled?newSession().catch(e=>toast(e.message)):toast('请从桌面应用启动真实 Agent。'));
$('#agent-stop').addEventListener('click',()=>window.fundDesktop.interrupt().then(desktopCall).catch(e=>toast(e.message)));
$('#agent-rename').addEventListener('click',async()=>{if(!D.current)return;const title=prompt('会话名称',D.current.title||'');if(!title?.trim())return;D.sessions=await desktopCall(window.fundDesktop.updateSession({threadId:D.current.threadId,title:title.trim()}));D.current=D.sessions.find(x=>x.threadId===D.current.threadId)||D.current;renderSessions();renderAgentPanel()});
$('#agent-pin').addEventListener('click',async()=>{if(!D.current)return;D.sessions=await desktopCall(window.fundDesktop.updateSession({threadId:D.current.threadId,pinned:!D.current.pinned}));D.current=D.sessions.find(x=>x.threadId===D.current.threadId);renderSessions();renderAgentPanel()});
$('#agent-archive').addEventListener('click',async()=>{if(!D.current)return;D.sessions=await desktopCall(window.fundDesktop.archiveSession(D.current.threadId));D.current=null;D.messages=[];render()});
async function deleteSession(threadId){const row=D.sessions.find(x=>x.threadId===threadId);if(!row)return;if(D.running){toast('请先停止或等待当前 Agent 任务完成。');return}if(!confirm(`删除对话“${row.title}”？删除后将从历史会话中移除。`))return;const wasCurrent=D.current?.threadId===threadId,outcome=await desktopCall(window.fundDesktop.deleteSession(threadId));D.sessions=Array.isArray(outcome)?outcome:(outcome?.sessions||[]);if(wasCurrent){D.current=null;D.messages=[];D.tools.clear();D.pendingInput=null;D.turnStartedAt=null}render();if(wasCurrent&&D.sessions.length){try{await resumeSession(D.sessions[0].threadId)}catch(e){toast(`会话已删除；下一条会话加载失败：${e.message}`);return}}toast(outcome?.warning?'对话已从本机历史移除；模型服务归档暂未完成。':'对话已删除')}
$('#agent-delete').addEventListener('click',()=>D.current&&deleteSession(D.current.threadId).catch(e=>toast(e.message)));
$('#agent-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#agent-form').requestSubmit()}});

async function bootstrap(){ensureChrome();setInterval(()=>{if(D.running&&$('#agent-elapsed'))$('#agent-elapsed').textContent=Math.max(0,Math.floor((Date.now()-(D.turnStartedAt||Date.now()))/1000))+' 秒'},1000);try{await refreshLocal();render();startMonitor();loadHoldings();loadShowcases();if(D.enabled)await initDesktop();else render()}catch(e){$('#panda-content').innerHTML=`<div class="panda-empty-page"><div><div class="empty-symbol">!</div><h2>本地服务尚未启动</h2><p>${esc(e.message)}</p></div></div>`}}
bootstrap();
